.product-faq {
  width: 100%;
  margin: 5px auto 5px;
  font-size: 95%;
}

.faq-container {
  border-radius: 6px;
  overflow: hidden;
  border: 1px solid #3b89bc;
  background-color: transparent;
}

.faq-container.border-bottom-only {
  border: none;
}
.faq-container.border-bottom-only .faq-question {
  padding-right: 0;
  padding-left: 0;
}
.faq-container.border-bottom-only .faq-answer {
  padding-right: 0;
  padding-left: 0;
}

.faq-item {
  border-bottom: 1px solid #3b89bc;
  padding: 0;
}

.faq-item:last-child {
  border-bottom: none;
}

.faq-question {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 8px 16px;
  cursor: pointer;
  font-weight: var(--font-weight-regular);
  position: relative;
  color: #181b1d;
  background-color: #f7fcff;
  font-size: 14px;
  line-height: 1.3;
  transition: background-color 0.3s ease, color 0.3s ease;
}

/* Hover effect removed - no color change on hover */

.faq-question-image,
.faq-question-svg {
  margin-right: 12px;
  flex-shrink: 0;
  width: 30px;
  height: 30px;
  border-radius: 4px;
  overflow: hidden;
  display: flex;
  align-items: center;
  justify-content: center;
}

.faq-question-image img {
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.faq-question-svg svg {
  width: 100%;
  height: 100%;
  max-width: 100%;
  max-height: 100%;
  display: block;
}

.faq-question-svg {
  background-color: transparent;
}

.faq-question-text {
  flex: 1;
}

.faq-toggle {
  font-size: 18px;
  font-weight: var(--font-weight-regular);
  transition: transform 0.3s ease;
  margin-left: 10px;
  flex-shrink: 0;
}

.faq-answer {
  padding: 0 16px;
  max-height: 0;
  overflow: hidden;
  transition: max-height 0.3s ease, padding 0.3s ease;
  color: #181b1d;
  background-color: #ffffff;
  font-size: 13px;
  line-height: 1.4;
}

.faq-item.active .faq-toggle {
  transform: rotate(45deg);
}

.faq-item.active .faq-answer {
  max-height: 150px;
  padding: 0 16px 3px;
  overflow-y: auto;
}

/* Custom scrollbar styling for FAQ answers */
.faq-answer::-webkit-scrollbar {
  width: 6px;
}
.faq-answer::-webkit-scrollbar-track {
  background: rgba(0, 0, 0, 0.1);
  border-radius: 3px;
}
.faq-answer::-webkit-scrollbar-thumb {
  background: rgba(0, 0, 0, 0.3);
  border-radius: 3px;
}
.faq-answer::-webkit-scrollbar-thumb:hover {
  background: rgba(0, 0, 0, 0.5);
}

/* Media queries for responsive design */
@media screen and (max-width: 768px) {
  .product-faq {
    font-size: 90%;
    width: 100%;
  }
  
  .faq-question {
    padding: 8px 14px;
    font-size: 14px;
  }
  
  .faq-question-image,
  .faq-question-svg {
    width: 26.25px;
    height: 26.25px;
    margin-right: 10px;
  }
  
  .faq-toggle {
    font-size: 16px;
  }
  
  .faq-answer {
    padding: 0 14px;
    font-size: 13px;
  }
  
  .faq-item.active .faq-answer {
    max-height: 120px;
    padding: 0 14px 3px;
  }

  /* Smaller scrollbar on mobile */
  .faq-answer::-webkit-scrollbar {
    width: 4px;
  }
}

@media screen and (max-width: 480px) {
  .product-faq {
    font-size: 85%;
    width: 100%;
    margin: 4.0px auto 4.0px;
  }
  
  .faq-question {
    padding: 8px 12px;
    font-size: 14px;
  }
  
  .faq-question-image,
  .faq-question-svg {
    width: 22.5px;
    height: 22.5px;
    margin-right: 8px;
  }
  
  .faq-toggle {
    font-size: 14px;
  }
  
  .faq-answer {
    padding: 0 12px;
    font-size: 13px;
    line-height: 1.3;
  }
  
  .faq-item.active .faq-answer {
    max-height: 100px;
    padding: 0 12px 3px;
  }

  /* Even smaller scrollbar on small mobile */
  .faq-answer::-webkit-scrollbar {
    width: 3px;
  }
}



